[{"order":1,"type":"heading","text":"Error Handling in Express.js: Centralized Error Handling"},{"order":2,"type":"subheading","text":"Introduction to Centralized Error Handling"},{"order":3,"type":"paragraph","text":"In Express.js, handling errors effectively is crucial for building robust and maintainable applications. Centralized error handling provides a structured approach to managing errors across your application, making it easier to debug and maintain."},{"order":4,"type":"paragraph","text":"Instead of handling errors in each route handler individually, you can define a middleware function that catches all errors and processes them in a consistent manner. This approach promotes code reusability and reduces redundancy."},{"order":5,"type":"subheading","text":"Implementing a Centralized Error Handler"},{"order":6,"type":"paragraph","text":"To implement a centralized error handler, you'll create a middleware function that takes four arguments: `err`, `req`, `res`, and `next`. Express.js recognizes this signature as an error-handling middleware."},{"order":7,"type":"code","text":"app.use((err, req, res, next) => { 
  console.error(err.stack); // Log the error stack trace
  res.status(500).send('Something broke!'); // Send a generic error response
});"},{"order":8,"type":"paragraph","text":"This middleware should be placed after all your route handlers and other middleware functions. When an error occurs in any of the preceding middleware or route handlers, Express.js will pass the error to this middleware."},{"order":9,"type":"subheading","text":"Example: Handling Asynchronous Errors"},{"order":10,"type":"paragraph","text":"When dealing with asynchronous operations (e.g., database queries, API calls), you need to ensure that errors are properly propagated to the centralized error handler. One common approach is to use `next(err)` to pass the error to the next error-handling middleware."},{"order":11,"type":"code","text":"app.get('/async-route', async (req, res, next) => {
  try {
    const result = await someAsyncOperation();
    res.send(result);
  } catch (err) {
    next(err); // Pass the error to the error handler
  }
});"},{"order":12,"type":"paragraph","text":"Alternatively, you can use a wrapper function to automatically catch errors in asynchronous route handlers. This reduces boilerplate code and ensures that errors are always handled."},{"order":13,"type":"code","text":"const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

app.get('/async-route', asyncHandler(async (req, res) => {
  const result = await someAsyncOperation();
  res.send(result);
}));"},{"order":14,"type":"subheading","text":"Custom Error Classes"},{"order":15,"type":"paragraph","text":"For more sophisticated error handling, you can define custom error classes that extend the built-in `Error` class. This allows you to provide more specific error information and handle different types of errors differently in your centralized error handler."},{"order":16,"type":"code","text":"class CustomError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
}

app.use((err, req, res, next) => {
  if (err instanceof CustomError) {
    res.status(err.statusCode).send(err.message);
  } else {
    console.error(err.stack);
    res.status(500).send('Something broke!');
  }
});"},{"order":17,"type":"subheading","text":"Best Practices"},{"order":18,"type":"bullet_point","text":"Log errors with sufficient detail (stack traces, request information) for debugging."},{"order":19,"type":"bullet_point","text":"Avoid exposing sensitive error information to the client in production environments."},{"order":20,"type":"bullet_point","text":"Use custom error classes to categorize and handle different types of errors."},{"order":21,"type":"bullet_point","text":"Consider using a dedicated logging library (e.g., Winston, Morgan) for more advanced logging capabilities."},{"order":22,"type":"subheading","text":"Conclusion"},{"order":23,"type":"paragraph","text":"Centralized error handling is an essential technique for building robust and maintainable Express.js applications. By implementing a centralized error handler, you can streamline error management, improve code reusability, and simplify debugging."}]
